import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.userData.handlers = {};

  const resources = [];
  let depthRotatePrim = null;

  // 1. Load watch mesh and normalize
  const glb = ctx.glbLoader.load('/prism-mock/orrery/meshes/watch.glb');
  const watch = glb.scene.clone();

  const box = new THREE.Box3().setFromObject(watch);
  const height = box.max.y - box.min.y;
  const scale = 2.2 / height;
  watch.scale.multiplyScalar(scale);

  const center = box.getCenter(new THREE.Vector3()).multiplyScalar(scale);
  watch.position.sub(center);

  // Apply PBR material to watch
  watch.traverse(child => {
    if (child.isMesh && child.material) {
      const oldMat = child.material;
      const newMat = new THREE.MeshStandardMaterial({
        roughness: 0.52,
        metalness: 0.55,
        clearcoat: 0.2,
        clearcoatRoughness: 0.4,
        map: oldMat.map,
        normalMap: oldMat.normalMap,
        roughnessMap: oldMat.roughnessMap,
        metalnessMap: oldMat.metalnessMap,
        aoMap: oldMat.aoMap,
      });
      child.material = newMat;
      child.castShadow = true;
      child.receiveShadow = true;
      resources.push(newMat);
      if (oldMat) resources.push(oldMat);
    }
  });

  // 2. Create plinth (radius 1.4, height 0.25, top at y=-1.1)
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new THREE.MeshStandardMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1;
  plinth.castShadow = true;
  plinth.receiveShadow = true;
  resources.push(plinthGeo, plinthMat);

  // 3. Create contact shadow (radial gradient, radius 1.6, opacity 0.55)
  const shadowGeo = new THREE.CircleGeometry(1.6, 64);
  const shadowTex = createRadialGradient(256, 256, 0.55);
  const shadowMat = new THREE.MeshStandardMaterial({
    map: shadowTex,
    transparent: true,
    depthWrite: false,
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.093, 0.01);
  shadow.rotation.x = -Math.PI / 2;
  resources.push(shadowGeo, shadowMat, shadowTex);

  // 4. Create backdrop gradient plane (7x6 at z=-2.5)
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropTex = createVerticalGradient();
  const backdropMat = new THREE.MeshStandardMaterial({
    map: backdropTex,
    emissive: 0x0b0b10,
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  resources.push(backdropGeo, backdropMat, backdropTex);

  // 5. Create text meshes using fontAtlas
  const textMeshes = [];

  const headline = createTextMesh(ctx, 'Calibre NA-01', 0.34, 0xe8ecf2);
  headline.position.set(-1.2, -1.5, 0.1);
  textMeshes.push(headline);

  const body = createTextMesh(ctx, 'Machined in-house. 41 mm. Grade 5 titanium.', 0.13, 0xe8ecf2);
  body.position.set(-2.0, -1.85, 0.1);
  textMeshes.push(body);

  const caption = createTextMesh(ctx, 'FROM 4200 USD / SHIPS IN 21 DAYS', 0.09, 0xff2a38);
  caption.position.set(-2.5, -2.2, 0.1);
  textMeshes.push(caption);

  // 6. Assemble scene
  root.add(backdrop);
  root.add(plinth);
  root.add(shadow);
  textMeshes.forEach(mesh => root.add(mesh));

  // 7. Create orbit group and apply orbit primitive
  const orbitGroup = new THREE.Group();
  orbitGroup.add(watch);
  root.add(orbitGroup);

  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(prim => {
      if (prim.name === 'orbit' && ctx.primitives?.orbit) {
        ctx.primitives.orbit(orbitGroup, prim.params);
      } else if (prim.name === 'depth-rotate') {
        depthRotatePrim = prim.params;
      }
    });
  }

  // 8. Setup hover handlers for depth-rotate primitive
  root.userData.handlers.onMouseEnter = () => {
    if (depthRotatePrim && ctx.primitives?.['depth-rotate']) {
      ctx.primitives['depth-rotate'](watch, depthRotatePrim);
    }
  };

  root.userData.handlers.onMouseLeave = () => {
    gsap.to(watch.rotation, {
      x: 0,
      y: 0,
