function createRadialGradient(width, height, opacity) {
  const data = new Uint8Array(width * height * 4);
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = Math.sqrt(centerX * centerX + centerY * centerY);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const dx = x - centerX;
      const dy = y - centerY;
      const dist = Math.sqrt(dx * dx + dy * dy) / maxRadius;
      const alpha = Math.max(0, 1 - dist) * opacity * 255;

      const idx = (y * width + x) * 4;
      data[idx] = 0;
      data[idx + 1] = 0;
      data[idx + 2] = 0;
      data[idx + 3] = Math.round(alpha);
    }
  }

  const tex = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

function createVerticalGradient() {
  const data = new Uint8Array(1 * 512 * 4);

  for (let i = 0; i < 512; i++) {
    const t = i / 511;
    let r, g, b;

    if (t < 0.55) {
      const s = t / 0.55;
      r = Math.round(0x0b + (0x10 - 0x0b) * s);
      g = Math.round(0x0b + (0x10 - 0x0b) * s);
      b = Math.round(0x10 + (0x17 - 0x10) * s);
    } else {
      const s = (t - 0.55) / 0.45;
      r = Math.round(0x10 + (0x16 - 0x10) * s);
      g = Math.round(0x10 + (0x16 - 0x10) * s);
      b = Math.round(0x17 + (0x1d - 0x17) * s);
    }

    data[i * 4] = r;
    data[i * 4 + 1] = g;
    data[i * 4 + 2] = b;
    data[i * 4 + 3] = 255;
  }

  const tex = new THREE.DataTexture(data, 1, 512, THREE.RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

function createTextMesh(ctx, text, size, color) {
  if (ctx.fontAtlas?.create) {
    return ctx.fontAtlas.create(text, { size, color });
  }

  const group = new THREE.Group();
  const geo = new THREE.PlaneGeometry(text.length * 0.08, size * 1.2);
  const mat = new THREE.MeshStandardMaterial({
    color,
    emissive: color,
    emissiveIntensity: 0.1,
  });
  group.add(new THREE.Mesh(geo, mat));
  return group;
}
